import type { ShortQuestion } from "../types-custom";

// ── 2-MARK QUESTIONS (2 marking points each) ──
export const HEREDITY10_VERY_SHORT: ShortQuestion[] = [
  { id: 1, question: "If a trait A exists in 10% of a population of an asexually reproducing species and a trait B exists in 60% of the same population, which trait is likely to have arisen earlier?", answer: "Trait B is likely to have arisen earlier. In asexual reproduction a variation is passed on by copying to every descendant, so a trait that appeared earlier has had more generations to spread and is therefore present in a larger part of the population.", keyPoints: ["Trait B (60%) is likely to be the earlier one", "An early variation is copied down more generations, so it spreads to more individuals"] },
  { id: 2, question: "How does the creation of variations in a species promote survival?", answer: "Variations give different individuals different advantages, so when the environment changes some individuals are better able to survive and reproduce. For example, heat-resistant bacteria survive a heat wave, so the species as a whole does not die out.", keyPoints: ["Variations give some individuals an advantage when conditions change", "Such individuals survive and reproduce, so the species survives (e.g. heat-resistant bacteria in a heat wave)"] },
  { id: 3, question: "How do Mendel's experiments show that traits may be dominant or recessive?", answer: "When Mendel crossed pure tall and pure short pea plants, all F1 plants were tall, so only one parental trait was expressed. When F1 plants were self-pollinated, the short trait reappeared in one quarter of the F2 plants, showing that it was present but hidden; the expressed trait is dominant and the hidden one recessive.", keyPoints: ["F1 showed only one parental trait (tall), with no medium plants", "Short trait reappeared in F2 in a 3 : 1 ratio, so tall is dominant and short recessive"] },
  { id: 4, question: "How do Mendel's experiments show that traits are inherited independently?", answer: "In a cross of tall round-seeded plants with short wrinkled-seeded plants, the F2 generation showed new combinations such as tall wrinkled and short round, apart from the parental types. This is possible only if height and seed shape are inherited independently of each other.", keyPoints: ["F2 of the dihybrid cross showed new combinations (tall wrinkled, short round)", "Such recombination shows that the two traits are inherited independently"] },
  { id: 5, question: "A man with blood group A marries a woman with blood group O and their daughter has blood group O. Is this information enough to tell which trait, A or O, is dominant? Why or why not?", answer: "No, it is not enough. If A is dominant, the man may carry a hidden O copy and pass it on, so the daughter gets O from both parents. If O is dominant, the daughter can also be O, so one child cannot settle which trait is dominant without knowing the parents' gene copies or more offspring.", keyPoints: ["The information is not sufficient to decide which trait is dominant", "The O daughter can be explained whichever trait is dominant, since the parents' hidden gene copies are unknown"] },
  { id: 6, question: "How is the sex of the child determined in human beings?", answer: "Women have two X chromosomes (XX) while men have one X and one Y (XY). Every egg carries an X, but a sperm carries either X or Y, so the sex of the child depends on the sperm: X gives a girl and Y gives a boy.", keyPoints: ["Female is XX and male is XY; every egg carries X", "Child receiving X from the father is a girl, receiving Y is a boy"] },
  { id: 7, question: "A Mendelian experiment consisted of breeding tall pea plants bearing violet flowers with short pea plants bearing white flowers. The progeny all bore violet flowers, but almost half of them were short. What is the genetic make-up of the tall parent?", answer: "The tall parent is TtWW (option c). All progeny are violet only if the parent is homozygous WW, and about half are short only if the tall parent is heterozygous Tt crossed with the short tt parent (Tt x tt gives 1 tall : 1 short).", keyPoints: ["All violet progeny means the tall parent is WW", "Half short progeny means it is Tt, so the genotype is TtWW"] },
  { id: 8, question: "A study found that children with light-coloured eyes are likely to have parents with light-coloured eyes. Can we say whether light eye colour is dominant or recessive? Why or why not?", answer: "No, we cannot. The observation only shows that the trait runs in families, and it fits both possibilities. To decide, we would need data on the eye colours of the children from crosses in which the parents differ, for example light-eyed x dark-eyed parents.", keyPoints: ["The data alone cannot show whether light eye colour is dominant or recessive", "Crosses between parents with different eye colours, and the resulting children, are needed"] },
  { id: 9, question: "Outline a project which aims to find the dominant coat colour in dogs.", answer: "Select pure-breeding dogs of two contrasting coat colours (say black and brown) and cross them. Observe the coat colour of all the F1 puppies; the colour seen in all of them is the dominant colour, and the colour that disappears is recessive.", keyPoints: ["Cross pure-breeding dogs having two different coat colours", "Colour appearing in all F1 puppies is dominant (confirm by crossing F1 to see the other colour reappear in F2)"] },
  { id: 10, question: "How is the equal genetic contribution of male and female parents ensured in the progeny?", answer: "Each germ cell (sperm or egg) receives only one chromosome from each pair, i.e. half the number of chromosomes of a body cell. At fertilisation the male and female gametes fuse, so the child gets one complete set from the father and one from the mother.", keyPoints: ["Each gamete carries one chromosome of each pair (a single gene set)", "Fusion of the two gametes gives each parent an equal share and restores the normal chromosome number"] },
  { id: 11, question: "What is heredity? What do the rules of heredity ensure?", answer: "Heredity is the passing of traits or characteristics from one generation to the next through genes. The rules of heredity ensure that traits are reliably inherited, so that offspring have the same basic body design as their parents along with small variations.", keyPoints: ["Heredity: transmission of traits (genetic information) from parents to offspring", "Rules of heredity ensure reliable inheritance of the common body design with subtle changes"] },
  { id: 12, question: "What is a trait? Give two examples of traits in human beings.", answer: "A trait is a specific observable feature or characteristic of an organism that is influenced by genes and by the environment. Examples are free or attached earlobes, and eye colour or height.", keyPoints: ["Trait: a specific observable feature/characteristic of an individual", "Examples: free or attached earlobes, eye colour or height"] },
  { id: 13, question: "What is a gene? Where are genes located?", answer: "A gene is a section of DNA that carries the information for making one particular protein, and it is the basic unit of heredity. Genes are located on the chromosomes in the nucleus of the cell.", keyPoints: ["Gene: section of DNA providing information for one protein; unit of heredity", "Genes lie on chromosomes inside the nucleus"] },
  { id: 14, question: "What are alleles?", answer: "Alleles are the different versions of a gene for the same trait, such as T for tallness and t for shortness. They occupy the same position on a pair of chromosomes, and an individual receives one allele from each parent.", keyPoints: ["Alleles: alternative forms of a gene for the same trait (e.g. T and t)", "Located at the same position on paired chromosomes, one inherited from each parent"] },
  { id: 15, question: "Distinguish between homozygous and heterozygous individuals with one example each.", answer: "A homozygous individual has two identical alleles for a trait, such as TT or tt. A heterozygous individual has two different alleles for the trait, such as Tt.", keyPoints: ["Homozygous: both alleles identical (TT or tt)", "Heterozygous: the two alleles are different (Tt)"] },
  { id: 16, question: "What are dominant and recessive traits? Give an example of each from pea plants.", answer: "A dominant trait is expressed even when only one copy of its gene is present, while a recessive trait is expressed only when both copies are the recessive allele. In pea plants tallness is dominant (T) and shortness is recessive (t).", keyPoints: ["Dominant trait shows with one copy; recessive shows only with two copies", "Example: tall (T) is dominant, short (t) is recessive"] },
  { id: 17, question: "Differentiate between genotype and phenotype using pea plant height as an example.", answer: "Genotype is the genetic make-up of an individual, that is, the alleles it carries, such as TT, Tt or tt. Phenotype is the observable trait, such as tall or short; both TT and Tt have the same phenotype (tall).", keyPoints: ["Genotype: the alleles present (TT, Tt, tt)", "Phenotype: the visible expression (tall or short); TT and Tt both look tall"] },
  { id: 18, question: "Give two reasons why Mendel chose the garden pea for his experiments.", answer: "Pea plants have a short life cycle and are easy to grow, so many progeny can be studied quickly. They also show many clear contrasting traits, and being bisexual they can be both self-pollinated and cross-pollinated.", keyPoints: ["Easy to grow with a short life cycle, giving many offspring quickly", "Clear contrasting visible traits, and both self- and cross-pollination are possible"] },
  { id: 19, question: "Why were there no medium-height plants in the F1 generation of Mendel's tall x short cross?", answer: "The F1 plants are Tt, and the dominant allele T completely masks the recessive allele t. Traits do not blend, so all the F1 plants are tall and none is of medium height.", keyPoints: ["F1 plants are heterozygous (Tt)", "Dominant T masks t; traits do not blend, so all are tall"] },
  { id: 20, question: "In a cross between a pure tall (TT) and a pure short (tt) pea plant, give the genotype and phenotype of F1 and the phenotypic ratio of F2.", answer: "All F1 plants are Tt and tall. When they are self-pollinated, the F2 has tall and short plants in the phenotypic ratio 3 : 1.", keyPoints: ["F1: all Tt, all tall", "F2: 3 tall : 1 short"] },
  { id: 21, question: "What is the genotypic ratio of the F2 generation in a monohybrid cross? How can it be confirmed by experiment?", answer: "The F2 genotypic ratio is 1 TT : 2 Tt : 1 tt. It can be confirmed by self-pollinating the F2 tall and short plants and counting their progeny: TT gives only tall, Tt gives tall and short in 3 : 1, and tt gives only short.", keyPoints: ["Genotypic ratio in F2: 1 TT : 2 Tt : 1 tt", "Confirm by self-pollinating F2 plants and counting the progeny of each"] },
  { id: 22, question: "In a dihybrid cross between pure tall round-seeded and short wrinkled-seeded pea plants, what is the phenotypic ratio in F2? Name the new combinations obtained.", answer: "The F2 phenotypic ratio is 9 tall round : 3 tall wrinkled : 3 short round : 1 short wrinkled, that is 9 : 3 : 3 : 1. The new combinations are tall wrinkled and short round.", keyPoints: ["F2 phenotypic ratio 9 : 3 : 3 : 1", "New combinations: tall with wrinkled seeds and short with round seeds"] },
  { id: 23, question: "In Mendel's cross of round green (RRyy) and wrinkled yellow (rrYY) pea plants, what will be the F1 plants like? Which traits are dominant?", answer: "The gametes are Ry and rY, so all F1 plants are RrYy and have round yellow seeds. Round and yellow seeds are therefore the dominant traits, and wrinkled and green are recessive.", keyPoints: ["F1 is RrYy, all round and yellow", "Round and yellow are dominant; wrinkled and green are recessive"] },
  { id: 24, question: "What is a mutation? Mention two causes.", answer: "A mutation is a change in the DNA sequence of an organism. It can be caused by mistakes during cell division or DNA copying, or by DNA-damaging agents such as chemicals and radiation.", keyPoints: ["Mutation: a change in the DNA sequence", "Causes: errors in DNA copying or cell division, and chemicals or radiation"] },
  { id: 25, question: "What is gene flow? How does it cause variation?", answer: "Gene flow, or migration, is the movement of genetic material or individuals from one population to another. When migrants reproduce in the new population, they introduce new gene versions there, which increases genetic variation.", keyPoints: ["Gene flow: movement of individuals or genes from one population to another", "Migrants that reproduce add new gene versions, increasing variation"] },
  { id: 26, question: "What is genetic recombination? Why does it lead to variation?", answer: "In sexual reproduction the offspring receive genetic material from two parents, which brings genes together in new combinations. This creates individuals with unique combinations of traits, so the offspring show more noticeable differences.", keyPoints: ["Recombination: new combinations of genes from two parents in sexual reproduction", "It produces unique individuals and greater diversity in the population"] },
  { id: 27, question: "Distinguish between genetic and environmental variation with one example each.", answer: "Genetic variation arises from differences in DNA and can be inherited, for example free or attached earlobes. Environmental variation is caused by external conditions such as diet, light or climate, for example a well-fed plant growing taller than a starved one.", keyPoints: ["Genetic variation: due to differences in DNA (e.g. earlobe type)", "Environmental variation: due to external conditions such as diet or light"] },
  { id: 28, question: "Why do organisms reproducing asexually, like a field of sugarcane, show very little variation?", answer: "An asexually reproducing organism gives offspring that are copies of the single parent. The only differences arise from tiny inaccuracies in DNA copying, so the individuals are very similar.", keyPoints: ["Offspring are genetically almost identical to the single parent", "Variation arises only from small errors (mutations) in DNA copying"] },
  { id: 29, question: "Why does sexual reproduction produce more variation than asexual reproduction?", answer: "In sexual reproduction, genes from two different parents combine in new ways in each offspring. This recombination, along with DNA copying errors, produces greater diversity than the mere copying seen in asexual reproduction.", keyPoints: ["Genes of two parents are combined in new ways (recombination)", "This adds to copying errors, giving far greater diversity than copying from one parent"] },
  { id: 30, question: "What is natural selection? Give an example.", answer: "Natural selection is the process by which the environment selects the variants that are better suited to it, so they survive and reproduce more. For example, bacteria able to withstand heat survive better in a heat wave and their number increases.", keyPoints: ["Environment selects the better-suited variants, which survive and reproduce more", "Example: heat-resistant bacteria surviving in a heat wave"] },
  { id: 31, question: "How does a gene control the height of a pea plant?", answer: "Plant height depends on the amount of a growth hormone, which is made with the help of an enzyme coded by a gene. If the gene works normally, the enzyme is efficient, plenty of hormone is made and the plant is tall.", keyPoints: ["Gene codes for an enzyme that helps make the growth hormone", "Efficient enzyme gives more hormone and a tall plant; less efficient enzyme gives a short plant"] },
  { id: 32, question: "Why must each germ cell have only one set of genes?", answer: "Body cells have two copies of every gene, one from each parent. If gametes also carried two sets, the number would double at every fertilisation, so each gamete carries one set so that the zygote gets the normal number.", keyPoints: ["Body cells carry two gene sets, one from each parent", "A single set in each gamete restores the normal number on fertilisation and keeps the species' DNA stable"] },
  { id: 33, question: "What is a chromosome? What is it made of?", answer: "A chromosome is a thread-like structure found in the nucleus of a cell. It is made of protein and a single molecule of DNA, and the genes are located along it.", keyPoints: ["Chromosome: thread-like structure in the nucleus", "Made of a DNA molecule and protein; carries the genes"] },
  { id: 34, question: "Why does the gene set exist as separate chromosomes and not as one long DNA thread?", answer: "Because the DNA is in separate pieces called chromosomes, each germ cell can take one chromosome of each pair independently. If the whole gene set were a single thread, traits such as R and y would be linked and could not be inherited independently.", keyPoints: ["Separate chromosomes are shared out independently into germ cells", "A single thread would link the traits and prevent new combinations"] },
  { id: 35, question: "What are autosomes and sex chromosomes? How many pairs of each do human beings have?", answer: "Autosomes are the chromosomes that are the same in males and females, and they determine most body traits. Sex chromosomes decide the sex of the person; humans have 22 pairs of autosomes and one pair of sex chromosomes.", keyPoints: ["Autosomes: non-sex chromosomes, 22 pairs in humans", "Sex chromosomes (X and Y): decide sex, one pair in humans"] },
  { id: 36, question: "Why is the sex of a child determined by the father and not by the mother?", answer: "The mother is XX, so all her eggs carry an X chromosome. The father is XY and produces X and Y sperms, so whether the child gets X (girl) or Y (boy) depends on the sperm that fertilises the egg.", keyPoints: ["Every egg from the mother carries an X chromosome", "The sperm carries either X or Y, so it decides the sex of the child"] },
  { id: 37, question: "How is sex determined in some reptiles?", answer: "In some reptiles such as certain turtles and crocodiles, sex is decided by environmental cues and not by genes. The temperature at which the fertilised eggs are kept decides whether males or females develop.", keyPoints: ["Sex is determined by an environmental cue, not by chromosomes", "The incubation temperature of the fertilised eggs decides male or female"] },
  { id: 38, question: "What does the ability of snails to change sex show about sex determination?", answer: "Some animals like snails can change their sex during their lifetime. This shows that in them sex is not fixed genetically but responds to environmental or social conditions.", keyPoints: ["Snails can change sex during life", "So sex is not genetically determined in them"] },
  { id: 39, question: "Why are the chances of having a boy or a girl equal in human beings?", answer: "A father produces X-bearing and Y-bearing sperms in equal numbers, and every egg carries X. Either type of sperm is equally likely to fertilise the egg, so half of the children are XX girls and half are XY boys.", keyPoints: ["Equal numbers of X and Y sperms, and all eggs carry X", "Each sperm type is equally likely to fertilise, giving 50% boys and 50% girls"] },
  { id: 40, question: "State Mendel's law of dominance.", answer: "When two different alleles for a trait are present in an individual, one allele may hide the effect of the other. The trait that is expressed is called dominant and the hidden one recessive, so an individual with at least one dominant allele shows the dominant trait.", keyPoints: ["Of two different alleles, one (dominant) masks the other (recessive)", "At least one dominant allele is enough to show the dominant trait"] },
  { id: 41, question: "State Mendel's law of segregation.", answer: "The two alleles for each trait separate from each other during the formation of gametes. Each gamete therefore carries only one allele, and the offspring get one allele from each parent.", keyPoints: ["The two alleles of a gene separate when gametes form", "Each gamete carries one allele; offspring inherit one from each parent"] },
  { id: 42, question: "State Mendel's law of independent assortment.", answer: "During the formation of gametes, the alleles of different genes separate independently of one another. As a result, different traits are inherited independently and new combinations of traits appear in the offspring.", keyPoints: ["Alleles of different genes segregate independently during gamete formation", "Traits are inherited independently, giving new combinations"] },
  { id: 43, question: "Who is called the Father of Modern Genetics? What was special about his method?", answer: "Gregor Johann Mendel is called the Father of Modern Genetics. He combined science with mathematics and was the first to count the individuals showing each trait in every generation, which helped him arrive at the laws of inheritance.", keyPoints: ["Gregor Mendel, from his experiments on garden pea plants", "He counted the individuals having each trait in each generation"] },
  { id: 44, question: "A heterozygous tall pea plant (Tt) is crossed with a short plant (tt). What will be the ratio of the progeny?", answer: "The Tt plant gives gametes T and t, and the tt plant gives only t. The progeny are Tt (tall) and tt (short) in the ratio 1 : 1.", keyPoints: ["Gametes: T and t from Tt; only t from tt", "Progeny: 1 tall (Tt) : 1 short (tt)"] },
  { id: 45, question: "Two heterozygous round-seeded pea plants (Rr) are crossed. What is the phenotypic ratio and the genotypic ratio of the offspring?", answer: "Each parent gives gametes R and r, so the offspring are 1 RR : 2 Rr : 1 rr. Since R is dominant, the phenotypic ratio is 3 round : 1 wrinkled.", keyPoints: ["Genotypic ratio 1 RR : 2 Rr : 1 rr", "Phenotypic ratio 3 round : 1 wrinkled"] },
  { id: 46, question: "Why does the short trait, absent in F1, reappear in the F2 generation of a tall x short cross?", answer: "F1 plants are Tt, so the t allele is present but masked by T. During gamete formation t separates from T, and when two t gametes meet in the F2 they form tt plants, which are short.", keyPoints: ["F1 plants carry the recessive allele t but it is masked by T", "Two t gametes can combine to form tt, so one quarter of F2 is short"] },
  { id: 47, question: "One tall pea plant on self-pollination gives only tall plants, and another gives both tall and short plants in a 3 : 1 ratio. What are their genotypes?", answer: "The plant giving only tall progeny is homozygous TT, as it makes only T gametes. The plant giving 3 tall : 1 short is heterozygous Tt, since Tt x Tt gives 1 TT : 2 Tt : 1 tt.", keyPoints: ["Only tall progeny: the parent is TT", "Tall and short in 3 : 1: the parent is Tt"] },
  { id: 48, question: "What is meant by the F1 and F2 generations?", answer: "The F1 generation, or first filial generation, is the progeny produced by crossing the two parent plants. The F2 generation, or second filial generation, is the progeny obtained by self-pollinating the F1 plants.", keyPoints: ["F1: first generation of progeny from the parental cross", "F2: second generation, produced from the F1 plants"] },
  { id: 49, question: "Name any four of the seven pairs of contrasting traits studied by Mendel in pea plants.", answer: "Mendel studied seed shape (round or wrinkled), seed colour (yellow or green) and plant height (tall or dwarf). He also studied flower colour (violet or white), flower position (axial or terminal), pod shape and pod colour.", keyPoints: ["Any two correct pairs, e.g. round/wrinkled seeds and yellow/green seeds", "Any two more, e.g. tall/short plants and violet/white flowers"] },
  { id: 50, question: "What are free and attached earlobes? How could you study their inheritance in your class?", answer: "Free and attached earlobes are two variants of the earlobe found in human populations. We list the students with each type, find the earlobe type of their parents, and correlate the two to suggest a rule of inheritance.", keyPoints: ["Two variants of a human trait: free and attached earlobes", "Survey the students and their parents and correlate the earlobe types"] },
  { id: 51, question: "What two purposes does inheritance from the previous generation serve?", answer: "Inheritance gives the offspring the common basic body design of the species. It also passes on small variations, so that the individuals of the next generation differ subtly from each other.", keyPoints: ["Provides the common basic body design of the species", "Passes on subtle variations that add to diversity"] },
  { id: 52, question: "Give two differences between sex determination in human beings and in reptiles such as turtles.", answer: "In human beings sex is largely genetic and depends on the sex chromosome (X or Y) received from the father. In reptiles such as some turtles it depends on the temperature at which the fertilised eggs are incubated.", keyPoints: ["Humans: genetic, decided by X or Y from the father", "Reptiles: environmental, decided by incubation temperature of the eggs"] },
];

// ── 3-MARK QUESTIONS (3 marking points each) ──
export const HEREDITY10_SHORT: ShortQuestion[] = [
  { id: 1, question: "Explain Mendel's monohybrid cross between a pure tall and a pure short pea plant up to the F2 generation. State the phenotypic and genotypic ratios.", answer: "The pure tall plant (TT) makes only T gametes and the pure short plant (tt) makes only t gametes, so all F1 plants are Tt and tall, with no medium plants. When the F1 plants are self-pollinated, each makes T and t gametes, and the Punnett square gives 1 TT : 2 Tt : 1 tt in the F2. Since T is dominant, the phenotypic ratio is 3 tall : 1 short. The short trait reappears because the t allele was present but masked in F1.", keyPoints: ["Parents TT x tt give all Tt (tall) F1 plants", "F2 genotypic ratio 1 TT : 2 Tt : 1 tt", "F2 phenotypic ratio 3 tall : 1 short, the recessive trait reappearing"] },
  { id: 2, question: "Differentiate between dominant and recessive traits.", answer: "A dominant trait is expressed even when only one copy of the allele is present, in both homozygous (TT) and heterozygous (Tt) individuals. A recessive trait is expressed only when both alleles are recessive (tt), and it is masked in the presence of the dominant allele. Dominant alleles are usually written as capital letters and recessive alleles as small letters. In peas, tallness is dominant and shortness is recessive.", keyPoints: ["Dominant: expressed with one or two copies; recessive: expressed only with two copies", "Recessive allele is masked by the dominant allele in heterozygotes", "Represented by capital and small letters respectively, e.g. T (tall) and t (short)"] },
  { id: 3, question: "Differentiate between genotype and phenotype. Explain with the example of flower colour in which A gives red and a gives white.", answer: "Genotype is the genetic make-up of an organism, that is, the pair of alleles it carries for a trait. Phenotype is the observable characteristic that results from the genotype and the environment. Here AA and Aa are different genotypes but both have the same phenotype, red flowers, because A is dominant. Only aa gives the phenotype of white flowers.", keyPoints: ["Genotype: the alleles present in the organism; phenotype: the visible trait", "AA and Aa both show red flowers (same phenotype, different genotypes)", "aa is the only genotype showing white flowers; phenotype also depends on the environment"] },
  { id: 4, question: "Differentiate between homozygous and heterozygous conditions. Give examples of genotypes of each type.", answer: "A homozygous individual has two identical alleles for a trait and is called pure for it. It may be homozygous dominant (TT) or homozygous recessive (tt), and it produces only one type of gamete. A heterozygous individual has two different alleles (Tt), and it produces two types of gametes, T and t. In a heterozygote only the dominant trait is seen.", keyPoints: ["Homozygous: two identical alleles (TT or tt); heterozygous: two different alleles (Tt)", "Homozygous forms one type of gamete; heterozygous forms two types (T and t)", "Heterozygote expresses only the dominant trait and the recessive allele stays hidden"] },
  { id: 5, question: "Differentiate between genetic variation and environmental variation. Mention how genetic variation arises.", answer: "Genetic variation is caused by differences in DNA and is inherited by the offspring. It arises through mutation, genetic recombination during sexual reproduction and gene flow between populations. Environmental variation is caused by external conditions such as climate, diet, light, moisture and minerals and is not inherited through DNA. For example, a plant given plenty of nutrients grows taller than an identical plant that is starved.", keyPoints: ["Genetic variation is due to differences in DNA and is inherited; environmental variation is due to external conditions", "Genetic variation arises by mutation, recombination and gene flow", "Example of environmental variation: difference in growth due to diet, light or climate"] },
  { id: 6, question: "Differentiate between a monohybrid cross and a dihybrid cross.", answer: "A monohybrid cross involves parents that differ in only one trait, such as tall and short plants. A dihybrid cross involves parents that differ in two traits, such as tall round-seeded and short wrinkled-seeded plants. The F2 phenotypic ratio of a monohybrid cross is 3 : 1, whereas that of a dihybrid cross is 9 : 3 : 3 : 1 and it includes new combinations of traits.", keyPoints: ["Monohybrid: one pair of contrasting traits; dihybrid: two pairs of contrasting traits", "Monohybrid F2 phenotypic ratio 3 : 1; dihybrid F2 ratio 9 : 3 : 3 : 1", "Only the dihybrid cross shows new combinations, proving independent inheritance"] },
  { id: 7, question: "Compare the variation produced in asexual reproduction with that in sexual reproduction.", answer: "In asexual reproduction one parent gives offspring that are almost identical to it. Variation arises only from small errors in DNA copying, as in four bacteria formed from one, or in a field of sugarcane. In sexual reproduction genes from two parents recombine in new ways, so the offspring show distinct and noticeable differences, as in human beings. Thus sexual reproduction generates much greater diversity than asexual reproduction.", keyPoints: ["Asexual: one parent, offspring nearly identical, variation only from DNA copying errors", "Sexual: two parents, genetic recombination gives new gene combinations", "Sexual reproduction therefore produces far greater and more noticeable diversity"] },
  { id: 8, question: "Explain a dihybrid cross between a pure tall plant with round seeds (TTRR) and a pure short plant with wrinkled seeds (ttrr) up to F2 with the phenotypic ratio.", answer: "The gametes of the parents are TR and tr, so all F1 plants are TtRr and are tall with round seeds; this shows that tallness and round seeds are dominant. Each F1 plant makes four types of gametes, TR, Tr, tR and tr, in equal numbers. The 16 combinations in the Punnett square give 9 tall round : 3 tall wrinkled : 3 short round : 1 short wrinkled. Tall wrinkled and short round are new combinations that were not seen in the parents.", keyPoints: ["Parental gametes TR and tr; F1 is all TtRr, tall with round seeds", "F1 forms four gamete types TR, Tr, tR and tr, giving 16 combinations", "F2 phenotypic ratio 9 : 3 : 3 : 1 with new combinations (tall wrinkled, short round)"] },
  { id: 9, question: "Round green seeded pea plants (RRyy) are crossed with wrinkled yellow seeded plants (rrYY). Give the F1 and F2 generations with their ratio and show how new combinations arise.", answer: "The gametes are Ry and rY, so all F1 plants are RrYy with round yellow seeds. On self-pollination each F1 plant forms RY, Ry, rY and ry gametes, which combine in 16 ways. The F2 has round yellow, round green, wrinkled yellow and wrinkled green seeds in the ratio 9 : 3 : 3 : 1. Round yellow and wrinkled green are the new combinations, since the parents were round green and wrinkled yellow.", keyPoints: ["F1: all RrYy, round and yellow seeds (dominant traits)", "F2 phenotypic ratio 9 round yellow : 3 round green : 3 wrinkled yellow : 1 wrinkled green", "New combinations arise as the genes for seed shape and colour recombine independently"] },
  { id: 10, question: "Why did Mendel select the pea plant for his experiments? Give three reasons.", answer: "Pea plants are easy to grow in pots or in the ground. Being annual with a short life cycle of two to three months, they give a large number of offspring that can be analysed in a short time. They have several easily visible contrasting traits, such as round or wrinkled seeds and tall or short plants. They are bisexual and can be both self-pollinated and cross-pollinated, so crosses can be controlled.", keyPoints: ["Easy to cultivate, with a short life cycle giving many offspring quickly", "Several easily recognisable contrasting traits (seed shape, height, flower colour)", "Bisexual flowers allow both self-pollination and cross-pollination"] },
  { id: 11, question: "Explain how genes control traits, taking the example of the height of a pea plant.", answer: "Cellular DNA is the information source for making proteins, and a section of DNA that codes for one protein is a gene. Plant height depends on the amount of a growth hormone, which is made with the help of an enzyme. If the gene for the enzyme is normal, the enzyme works efficiently, plenty of hormone is made and the plant is tall. If the gene is altered so that the enzyme is less efficient, less hormone is made and the plant is short.", keyPoints: ["A gene is a section of DNA that provides information for making a protein (enzyme)", "Enzyme efficiency decides the amount of growth hormone made", "Efficient enzyme gives a tall plant; altered, less efficient enzyme gives a short plant"] },
  { id: 12, question: "Explain with a cross how the sex of a child is determined in human beings.", answer: "A woman has the sex chromosomes XX and a man has XY. The mother produces eggs that all carry X, while the father produces two kinds of sperms, X-bearing and Y-bearing, in equal numbers. If an X sperm fertilises the egg the child is XX, a girl; if a Y sperm fertilises it the child is XY, a boy. So half the children are boys and half are girls, and the father's sperm decides the sex.", keyPoints: ["Mother XX gives only X eggs; father XY gives X and Y sperms", "X sperm + X egg gives a girl (XX); Y sperm + X egg gives a boy (XY)", "Probability of a boy or a girl is equal, and the sex depends on the father's contribution"] },
  { id: 13, question: "Different species use different strategies for sex determination. Explain with examples.", answer: "In some animals sex is determined by the environment. In some reptiles such as certain turtles and crocodiles, the temperature at which the fertilised eggs are incubated decides whether the young will be male or female. In snails and some fish the individual can change sex during its lifetime, showing that sex is not genetically fixed. In human beings sex is largely genetic and depends on the X or Y chromosome received from the father.", keyPoints: ["Reptiles: incubation temperature of eggs determines sex", "Snails (and some fish) can change sex, so sex is not genetically determined", "Human beings: genetic, decided by the X or Y chromosome inherited from the father"] },
  { id: 14, question: "Explain with the example of bacteria how the environment selects variants, and state why this is important for a species.", answer: "In a population of bacteria there are small variations produced by DNA copying errors, and some bacteria can withstand heat. When a heat wave occurs, most normal bacteria die, but the heat-resistant variants survive and multiply. As a result the population becomes mostly heat-resistant, and the species continues to survive. This selection of variants by environmental factors is called natural selection, and it forms the basis of evolution.", keyPoints: ["Variations exist in the population, e.g. some bacteria are heat-resistant", "In a heat wave the resistant variants survive and multiply while others die", "Selection of variants by the environment is natural selection and gives the species survival and evolution"] },
  { id: 15, question: "Describe how variations accumulate over successive generations.", answer: "Inheritance gives the next generation the common basic body design together with subtle changes. When an individual reproduces, its offspring differ slightly from it, and each of them passes on the inherited differences plus newly created ones. In the second generation, therefore, each individual has differences inherited from its parent as well as new ones, so every individual becomes different from all the others. Some differences are unique, and others are inherited from the parents who were different from each other.", keyPoints: ["Each generation inherits the basic body design plus small changes", "The next generation carries inherited differences plus newly created ones", "Over generations diversity increases, with each individual different from the others"] },
  { id: 16, question: "State Mendel's three laws of inheritance.", answer: "The law of dominance says that when two different alleles are present, the dominant one is expressed and the recessive one is hidden. The law of segregation says that the two alleles of a gene separate during gamete formation, so each gamete carries one allele and each offspring gets one allele from each parent. The law of independent assortment says that alleles of different genes separate independently during gamete formation, so traits are inherited independently. These laws were framed from his experiments on pea plants.", keyPoints: ["Law of dominance: dominant allele masks the recessive allele", "Law of segregation: two alleles separate at gamete formation, one to each gamete", "Law of independent assortment: alleles of different genes are inherited independently"] },
  { id: 17, question: "Explain the relationship between chromosome, DNA and gene.", answer: "A chromosome is a thread-like structure in the nucleus, made of protein and one molecule of DNA. DNA carries the information for making proteins in the cell. A gene is a section of DNA that codes for one particular protein, so many genes lie along each chromosome. Genes are the basic units of heredity and pass from parents to offspring, and they carry information that decides the traits.", keyPoints: ["Chromosome: thread-like structure in the nucleus made of DNA and protein", "DNA contains the instructions for making proteins", "Gene: a section of DNA coding for one protein; the unit of heredity located on chromosomes"] },
  { id: 18, question: "How do germ cells get one set of genes, and how is the normal chromosome number restored in the progeny?", answer: "Body cells contain two copies of each chromosome, one from each parent. During the formation of germ cells, each germ cell receives only one chromosome from each pair, which may be of maternal or paternal origin. Thus each gamete has half the chromosome number, or one gene set. When sperm and egg fuse at fertilisation, the full number is restored in the zygote, keeping the DNA of the species stable.", keyPoints: ["Body cells have two copies of each chromosome, one from each parent", "Each germ cell takes one chromosome from each pair (half the number)", "Fertilisation restores the normal number, ensuring the stability of the species' DNA"] },
  { id: 19, question: "The F2 generation of a cross between round yellow and wrinkled green pea plants (RrYy self-pollinated) had 315 round yellow, 108 round green, 101 wrinkled yellow and 32 wrinkled green seeds. Explain how these figures show independent inheritance.", answer: "The numbers are close to the 9 : 3 : 3 : 1 ratio expected from 556 seeds. Round green and wrinkled yellow are new combinations that were not present in the parents. If shape and colour genes were linked, only the parental combinations would appear. Their appearance shows that the genes for seed shape and seed colour are inherited independently, because they lie on separate chromosomes.", keyPoints: ["Ratio is about 9 : 3 : 3 : 1 in 556 seeds", "New combinations (round green, wrinkled yellow) appear in F2", "Seed shape and colour are inherited independently, being on separate chromosomes"] },
  { id: 20, question: "Explain mutation, genetic recombination and gene flow as sources of genetic variation.", answer: "A mutation is a change in the DNA sequence, caused by mistakes in cell division or copying, by chemicals or radiation, or by a viral infection, and it may be harmful, beneficial or neutral. Genetic recombination occurs in sexual reproduction, when the offspring inherit genes from two parents and get new combinations of genes. Gene flow, or migration, is the movement of individuals or genes from one population to another, and the migrants bring new gene versions into the population when they reproduce.", keyPoints: ["Mutation: change in DNA sequence from copying errors or DNA-damaging agents", "Recombination: new combinations of genes from two parents in sexual reproduction", "Gene flow: migration of individuals or genes between populations adds new variants"] },
  { id: 21, question: "Tall pea plants with violet flowers were crossed with short plants with white flowers. All progeny were violet, but almost half were short. Work out the genotype of the tall parent and show the cross.", answer: "The short white parent is ttww and makes only tw gametes. All the progeny are violet, so the tall parent must be homozygous for violet (WW). About half are short, so it must be heterozygous for height (Tt); thus the tall parent is TtWW. It gives TW and tW gametes, and with tw the progeny are TtWw (tall violet) and ttWw (short violet) in equal numbers.", keyPoints: ["Short white parent is ttww, giving only tw gametes", "All violet means WW; half short means Tt, so the tall parent is TtWW", "Progeny: 1 TtWw (tall, violet) : 1 ttWw (short, violet)"] },
  { id: 22, question: "A heterozygous tall pea plant (Tt) is crossed with a short plant (tt), and another Tt plant is self-pollinated. Compare the ratios of the two crosses.", answer: "In the cross Tt x tt, the gametes are T and t from one parent and only t from the other. The progeny are 1 Tt (tall) : 1 tt (short), a 1 : 1 ratio for both genotype and phenotype. In the self-pollination Tt x Tt, the progeny are 1 TT : 2 Tt : 1 tt, so the genotypic ratio is 1 : 2 : 1 and the phenotypic ratio is 3 tall : 1 short. Thus the presence of short plants in the progeny shows that the tall parent is heterozygous.", keyPoints: ["Tt x tt gives 1 tall : 1 short (1 Tt : 1 tt)", "Tt x Tt gives 1 TT : 2 Tt : 1 tt, i.e. 3 tall : 1 short", "Short progeny from tall parents show that the tall parents carry the recessive allele"] },
  { id: 23, question: "What was special about Mendel's approach that helped him discover the laws of inheritance?", answer: "Mendel was the first to combine his knowledge of science and mathematics in studying inheritance. He chose pure-breeding pea plants and followed one or two contrasting traits at a time. He also counted the number of individuals showing each trait in every generation, from the parents to the F1 and F2. The ratios obtained from these counts, such as 3 : 1 and 9 : 3 : 3 : 1, led him to the laws of inheritance.", keyPoints: ["Blended science with mathematics in studying inheritance", "Studied clear contrasting traits in pure-breeding pea plants over generations", "Counted the individuals of each type and derived ratios leading to the laws"] },
  { id: 24, question: "Why can the phenotype of an organism not be predicted from its genotype alone? Explain with an example.", answer: "The phenotype is produced by the genotype together with the environment. For example, a pea plant with the genes for tallness (TT) will not grow tall if it is starved of nutrients or light. Such a change caused by the environment is an environmental variation, and it is not passed on to the offspring through DNA. Only the differences in the genes are inherited by the next generation.", keyPoints: ["Phenotype depends on the genotype and the environment", "Example: a plant with genes for tallness stays short in poor conditions", "Environmental effects are not inherited, only genetic differences are"] },
  { id: 25, question: "Why do children resemble their parents and yet differ from them and from each other?", answer: "Children inherit their genes from their parents through the rules of heredity, so they show the basic features of a human being and many family traits. Each child gets a different mixture of paternal and maternal alleles by recombination in sexual reproduction, so every child shows a new combination of traits. Small changes in DNA (mutations) also add to the differences. Hence they are similar to, but not identical with, their parents.", keyPoints: ["Genes inherited from parents give the common design and family traits", "Recombination of maternal and paternal alleles gives each child a new combination", "Mutations add further differences, so children are similar but not identical"] },
  { id: 26, question: "Describe an activity to study the inheritance of earlobe types in your class and state what conclusion it may lead to.", answer: "Observe the ears of all students and prepare a list of those with free earlobes and those with attached earlobes. Calculate the percentage of students having each type. Then find the earlobe type of the parents of each student and correlate it with the earlobe type of the student. If children with attached earlobes are seen only when the parents have a particular pattern, it suggests a rule of inheritance, showing which variant is dominant and which is recessive.", keyPoints: ["Classify students as free or attached earlobes and calculate the percentage of each", "Find the earlobe type of parents and correlate with that of the student", "Use the correlation to suggest a possible rule (dominant or recessive) of inheritance"] },
  { id: 27, question: "How can we confirm that the F2 generation of a tall x short cross has TT, Tt and tt in a 1 : 2 : 1 ratio? Show the Punnett square.", answer: "In the F2 generation the gametes of the F1 (Tt x Tt) combine as T with T, T with t, t with T and t with t, giving TT, Tt, Tt and tt, that is 1 : 2 : 1. To confirm this, allow all the F2 plants to self-pollinate separately and count the progeny of each. About one quarter of the plants (TT) will give only tall plants, half (Tt) will give tall and short plants in 3 : 1, and one quarter (tt) will give only short plants.", keyPoints: ["Punnett square of Tt x Tt gives TT, Tt, Tt, tt (1 : 2 : 1)", "Self-pollinate individual F2 plants and count their progeny", "TT gives all tall, Tt gives 3 tall : 1 short, tt gives all short, in the ratio 1 : 2 : 1"] },
  { id: 28, question: "Explain the inheritance of chromosomes in human beings, with the numbers of autosomes and sex chromosomes in the gametes and the zygote.", answer: "A human body cell has 46 chromosomes, arranged as 23 pairs, of which 22 pairs are autosomes and one pair is the sex chromosomes. Each gamete has 23 chromosomes: 22 autosomes plus one sex chromosome, X in every egg and X or Y in a sperm. On fertilisation the egg (23) and the sperm (23) fuse to make a zygote with 46 chromosomes, half from each parent. The zygote is XX if the sperm carried X and XY if it carried Y.", keyPoints: ["Body cell: 46 chromosomes = 22 pairs of autosomes + 1 pair of sex chromosomes", "Each gamete has 23 chromosomes (22 autosomes + X or Y)", "Fertilisation restores 46 in the zygote, with half from each parent, XX or XY"] },
  { id: 29, question: "In the F2 generation of a dihybrid cross RrYy x RrYy, list the nine genotypes and the phenotype of each group.", answer: "The 16 combinations of the Punnett square give nine genotypes in the ratio 1 RRYY : 2 RRYy : 2 RrYY : 4 RrYy : 1 RRyy : 2 Rryy : 1 rrYY : 2 rrYy : 1 rryy. RRYY, RRYy, RrYY and RrYy (9 in 16) are round yellow. RRyy and Rryy (3 in 16) are round green, rrYY and rrYy (3 in 16) are wrinkled yellow, and rryy (1 in 16) is wrinkled green.", keyPoints: ["Nine genotypes in the ratio 1 : 2 : 2 : 4 : 1 : 2 : 1 : 2 : 1", "Round yellow (9): RRYY, RRYy, RrYY, RrYy; round green (3): RRyy, Rryy", "Wrinkled yellow (3): rrYY, rrYy; wrinkled green (1): rryy"] },
  { id: 30, question: "In a monohybrid cross of Tt x Tt among 1200 F2 pea plants, how many plants would you expect to be tall, short, TT, Tt and tt? Show your reasoning.", answer: "Tt x Tt gives TT, Tt, Tt and tt, so the genotypic ratio is 1 : 2 : 1. Out of 1200 plants, about 300 will be TT, 600 will be Tt and 300 will be tt. Since T is dominant, TT and Tt are both tall, giving 900 tall plants, while the 300 tt plants are short. The phenotypic ratio is therefore 3 : 1.", keyPoints: ["Genotypic ratio 1 TT : 2 Tt : 1 tt, i.e. about 300 : 600 : 300", "Tall = TT + Tt = about 900 plants", "Short = tt = about 300 plants, a 3 : 1 phenotypic ratio"] },
  { id: 31, question: "How do asexually reproducing organisms inherit their traits? Compare with the inheritance in sexually reproducing organisms.", answer: "In asexual reproduction a single parent makes a copy of its DNA and passes it on to the offspring. All the genes of the offspring therefore come from one parent, and the offspring are almost identical to it, apart from small copying errors. In sexual reproduction each offspring receives two sets of genes, one from each parent, so it inherits two versions of each trait. The rules of inheritance are the same in both cases, but the outcome differs.", keyPoints: ["Asexual: offspring inherit a copy of the DNA of a single parent", "Sexual: offspring inherit one gene set from each of two parents, i.e. two versions of each trait", "Asexual offspring are nearly identical to the parent while sexual offspring show diversity"] },
  { id: 32, question: "Why are variations useful to a species rather than to an individual? Why does sexual reproduction help in maximising the number of successful variations?", answer: "The environment may change, as in a heat wave, and not all individuals are equally suited to the new condition. If a species has many variations, at least some individuals are likely to survive and reproduce, so the species does not die out. Asexual reproduction gives only small variations through copying errors, but sexual reproduction mixes genes of two parents to produce many new combinations. More combinations mean a greater chance that some are successful in a changing environment.", keyPoints: ["Variations mean some individuals survive when the environment changes, so the species survives", "Asexual reproduction gives few variations from copying errors only", "Sexual reproduction creates many new gene combinations, so more successful variations"] },
  { id: 33, question: "Can a recessive trait appear in a child when neither parent shows it? Explain with a cross.", answer: "Yes, if both parents are heterozygous carriers. Consider two tall plants, both Tt, which show the dominant trait because T masks t. Each parent forms T and t gametes, and when two t gametes meet, the offspring is tt and it is short. On average one out of four offspring will be short, while three out of four will be tall.", keyPoints: ["Both parents must be heterozygous carriers (Tt) showing the dominant trait", "Two recessive gametes (t + t) may unite to form a tt offspring", "One quarter of the offspring show the recessive trait (3 : 1 ratio)"] },
];
